/* Generated by scripts/offline-build.mjs. Register explicitly at the app's root scope. */
const VERSION = '__OFFLINE_VERSION__'
const ASSET_COUNT = __OFFLINE_ASSET_COUNT__
const TOTAL_BYTES = __OFFLINE_TOTAL_BYTES__
const PRECACHE = __OFFLINE_PRECACHE__
const CACHE_PREFIX = 'cha-waves-offline-'
const CACHE_NAME = `${CACHE_PREFIX}${VERSION}`

function toHex(buffer) {
  return [...new Uint8Array(buffer)].map((byte) => byte.toString(16).padStart(2, '0')).join('')
}

async function isValidResponse(response, expectedHash) {
  if (!response || response.status !== 200 || response.type === 'opaque' || response.redirected) return false
  const responseUrl = new URL(response.url)
  if (responseUrl.origin !== self.location.origin) return false
  const digest = await crypto.subtle.digest('SHA-256', await response.clone().arrayBuffer())
  return toHex(digest) === expectedHash
}

async function cacheIsComplete() {
  return Promise.all(PRECACHE.map(async (asset) => {
    const cached = await caches.match(new URL(asset.url, self.registration.scope).href, { cacheName: CACHE_NAME })
    return cached ? isValidResponse(cached, asset.sha256) : false
  })).then((results) => results.every(Boolean))
}

async function populateCache() {
  if (await cacheIsComplete()) return

  // Verify the whole download before replacing any entries, including during repair.
  const downloads = []
  for (const asset of PRECACHE) {
    const url = new URL(asset.url, self.registration.scope)
    if (url.origin !== self.location.origin) throw new Error(`Cross-origin precache URL: ${asset.url}`)
    const response = await fetch(url.href, { cache: 'no-store', credentials: 'same-origin', redirect: 'error' })
    if (!await isValidResponse(response, asset.sha256)) throw new Error(`Precache verification failed: ${asset.url}`)
    downloads.push({ url: url.href, response })
  }
  const existed = (await caches.keys()).includes(CACHE_NAME)
  const cache = await caches.open(CACHE_NAME)
  try {
    for (const { url, response } of downloads) await cache.put(url, response)
  } catch (error) {
    if (!existed) await caches.delete(CACHE_NAME)
    throw error
  }
}

self.addEventListener('install', (event) => { event.waitUntil(populateCache()) })

self.addEventListener('message', (event) => {
  if (!event.data) return
  if (event.data.type === 'ACTIVATE_UPDATE') {
    event.waitUntil((async () => {
      if (await cacheIsComplete()) await self.skipWaiting()
    })())
    return
  }
  if (event.data.type === 'REPAIR_CACHE') {
    event.waitUntil((async () => {
      try {
        await populateCache()
        event.ports?.[0]?.postMessage({ type: 'REPAIR_COMPLETE', ready: true })
      } catch {
        event.ports?.[0]?.postMessage({ type: 'REPAIR_COMPLETE', ready: false })
      }
    })())
    return
  }
  if (event.data.type === 'GET_STATUS') {
    event.waitUntil((async () => {
      const reply = {
        type: 'STATUS',
        version: VERSION,
        assetCount: ASSET_COUNT,
        totalBytes: TOTAL_BYTES,
        ready: await cacheIsComplete(),
      }
      if (event.ports?.[0]) event.ports[0].postMessage(reply)
      else event.source?.postMessage(reply)
    })())
  }
})

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    await self.clients.claim()
    const windows = await self.clients.matchAll({ type: 'window', includeUncontrolled: true })
    if (windows.length > 0) return
    const keys = await caches.keys()
    await Promise.all(keys
      .filter((key) => key.startsWith(CACHE_PREFIX) && key !== CACHE_NAME)
      .map((key) => caches.delete(key)))
  })())
})

self.addEventListener('fetch', (event) => {
  const request = event.request
  if (request.method !== 'GET') return
  const requestUrl = new URL(request.url)
  if (requestUrl.origin !== self.location.origin || requestUrl.search || requestUrl.hash) return

  const pathname = requestUrl.pathname === '/' ? '/index.html' : requestUrl.pathname
  const asset = PRECACHE.find((entry) => entry.url === pathname)
  // Previous workers may have cached content-hashed chunks absent from this version's manifest.
  // CacheStorage is asynchronous, so look up that exact request and pass through if no old copy exists.
  if (!asset) {
    event.respondWith((async () => {
      const keys = await caches.keys()
      for (const key of keys) {
        if (!key.startsWith(CACHE_PREFIX) || key === CACHE_NAME) continue
        const response = await caches.match(requestUrl.href, { cacheName: key })
        if (response) return response
      }
      return fetch(request)
    })())
    return
  }

  event.respondWith((async () => {
    const currentResponse = await caches.match(new URL(asset.url, self.registration.scope).href, { cacheName: CACHE_NAME })
    if (currentResponse) return currentResponse

    // A tab left open across an update can still request its old content-hashed chunks.
    const keys = await caches.keys()
    for (const key of keys) {
      if (!key.startsWith(CACHE_PREFIX) || key === CACHE_NAME) continue
      const response = await caches.match(requestUrl.href, { cacheName: key })
      if (response) return response
    }
    return fetch(request)
  })())
})
